GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }
    if (tour.isEmpty()) {
        return new DefaultGraphPath<>();
    }

    V startVertex = null;
    Map<V, List<E>> adjacencyList = new HashMap<>();
    Set<V> vertices = new HashSet<>();

    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        vertices.add(source);
        vertices.add(target);

        adjacencyList.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        if (!graph.getType().isDirected()) {
            adjacencyList.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
        }
    }

    for (V vertex : vertices) {
        if (adjacencyList.get(vertex).size() % 2 != 0) {
            throw new IllegalArgumentException("Graph is not eulerian, cannot form a tour");
        }
    }

    List<E> pathEdges = new ArrayList<>();
    Deque<V> stack = new ArrayDeque<>();
    startVertex = vertices.iterator().next();
    stack.push(startVertex);

    while (!stack.isEmpty()) {
        V currentVertex = stack.peek();
        List<E> edges = adjacencyList.get(currentVertex);

