private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    if (minLabelBucket == null) {
        throw new IllegalArgumentException("Bucket with minLabel does not exist");
    }

    Set<Integer> zeroLabelBucket = bucketsByLabel.get(0);
    if (zeroLabelBucket == null) {
        throw new IllegalArgumentException("Bucket with label 0 does not exist");
    }

    for (Integer vertex : minLabelBucket) {
        labels.set(vertex, 0);
        zeroLabelBucket.add(vertex);
    }

    minLabelBucket.clear();
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    Set<Integer> fromBucket = bucketsByLabel.get(minLabel);
    Set<Integer> toBucket = bucketsByLabel.get(0);

    if (fromBucket == null || toBucket == null) {
        throw new IllegalArgumentException("Buckets are not properly initialized");
    }

    for (Integer vertex : fromBucket) {
        if (vertex < 0 || vertex >= labels.size()) {
            throw new IllegalArgumentException("Vertex index out of bounds");
        }
        labels.set(vertex, 0); // Update the label to 0
        toBucket.add(vertex); // Move vertex to bucket 0
    }

    fromBucket.clear(); // Clear the bucket with label minLabel
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    Set<Integer> bucketToMove = bucketsByLabel.get(minLabel);
    if (bucketToMove == null) {
        return; // No vertices to move
    }

    Set<Integer> targetBucket = bucketsByLabel.get(0);
    if (targetBucket == null) {
        bucketsByLabel.set(0, new HashSet<>());
        targetBucket = bucketsByLabel.get(0);
    }

    for (Integer vertex : bucketToMove) {
        targetBucket.add(vertex);
        labels.set(vertex, 0); // Update the label of the vertex to 0
    }

