String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (++i >= len) {
                throw new Exception("Invalid escape character sequence");
            }
            c = str.charAt(i);
            switch (c) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u': {
                    if (i + 4 >= len) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    int value = 0;
                    for (int j = 0; j < 4; j++) {
                        c = str.charAt(++i);
                        switch (c) {
                            case '0': case '1': case '2': case '3': case '4':
                            case '5': case '6': case '7': case '8': case '9':
                                value = (value << 4) + (c - '0');
                                break;
                            case 'a': case 'b': case 'c': case 'd': case 'e': case 'f':
                                value = (value << 4) + (10 + c - 'a');
                                break;
                            case 'A': case 'B': case 'C': case 'D': case 'E': case 'F':
                                value = (value << 4) + (10 + c - 'A');
                                break;
                            default:
                                throw new Exception("Invalid Unicode escape sequence");
                        }
                    }
                    sb.append((char) value);
                    break;
                }
                default:
                    throw new Exception("Invalid escape character '" + c + "'");
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

