public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path must not be null");
    }

    // Normalize the paths to ensure they use the correct separator
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');

    // Handle leading slash in relative path, which means it's an absolute path
    if (relativePath.startsWith("/")) {
        return relativePath;
    }

    // Split the paths by the "/" separator
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Start with the path parts
    List<String> resultParts = new ArrayList<>(Arrays.asList(pathParts));

    // Process each part of the relative path
    for (String part : relativePathParts) {
        if (part.equals("..")) {
            // Move up one directory if possible
            if (!resultParts.isEmpty() && !resultParts.get(resultParts.size() - 1).isEmpty()) {
                resultParts.remove(resultParts.size() - 1);
            }
        } else if (!part.isEmpty() && !part.equals(".")) {
            // Add non-empty parts that are not "."
            resultParts.add(part);
        }
    }

    // Join the parts back together using "/"
    return String.join("/", resultParts);
}

String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must be non-null");
    }

    // Normalize the path by removing trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }

    // Split the relative path into components
    String[] relativeComponents = relativePath.split("/");

    // Create a list of the original path components
    List<String> components = new ArrayList<>(List.of(path.split("/")));

    // Process each component of the relative path
    for (String component : relativeComponents) {
        if (component.equals("..")) {
            // Move up one directory if possible
            if (components.size() > 0 && !components.get(components.size() - 1).isEmpty()) {
                components.remove(components.size() - 1);
            }
        } else if (component.equals(".") || component.isEmpty()) {
            // Ignore current directory marker and empty components
            continue;
        } else {
            // Add the component to the path
            components.add(component);
        }
    }

    // Join the components back into a single path
    return String.join("/", components);
}

String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Normalize the path and relativePath by removing any trailing '/'
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Process the relative path components
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            // Move up one directory if possible
            if (pathComponents.length > 0) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else if (!component.equals(".")) {
            // Add the component to the path
            String[] newPathComponents = new String[pathComponents.length + 1];
            System.arraycopy(pathComponents, 0, newPathComponents, 0, pathComponents.length);
            newPathComponents[pathComponents.length] = component;
            pathComponents = newPathComponents;
        }
    }

    // Build the resulting path
    return String.join("/", pathComponents);
}

