String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath must not be null");
    }

    // Normalize the paths to ensure consistent behavior with file separators
    String normalizedPath = path.replace("\\", "/");
    String normalizedRelativePath = relativePath.replace("\\", "/");

    // Handle edge cases where the relative path is empty or "."
    if (normalizedRelativePath.isEmpty() || normalizedRelativePath.equals(".")) {
        return normalizedPath;
    }

    // Handle the case where the relative path is ".."
    if (normalizedRelativePath.equals("..")) {
        int lastSlashIndex = normalizedPath.lastIndexOf('/');
        if (lastSlashIndex == -1) {
            return ""; // If there's no parent directory, return an empty string
        }
        return normalizedPath.substring(0, lastSlashIndex);
    }

    // Split the paths into components
    String[] pathComponents = normalizedPath.split("/");
    String[] relativePathComponents = normalizedRelativePath.split("/");

    // Process the relative path components
    for (String component : relativePathComponents) {
        if (component.equals(".")) {
            continue; // Current directory, do nothing
        } else if (component.equals("..")) {
            // Move up one directory
            if (pathComponents.length > 0) {
                String[] newPathComponents = new String[pathComponents.length - 1];
                System.arraycopy(pathComponents, 0, newPathComponents, 0, pathComponents.length - 1);
                pathComponents = newPathComponents;
            }
        } else {
            // Add the component to the path
            String[] newPathComponents = new String[pathComponents.length + 1];
            System.arraycopy(pathComponents, 0, newPathComponents, 0, pathComponents.length);
            newPathComponents[pathComponents.length] = component;
            pathComponents = newPathComponents;
        }
    }

    // Join the path components back into a single string
    return String.join("/", pathComponents);
}

